import{_ as t,D as n,o as r,c,m as l,a as i,G as a,S as y}from"./chunks/framework.DuIEtbrD.js";const A=JSON.parse('{"title":"谈谈国际化的使用姿势(i18n)","description":"本文深入探讨i18n(国际化)在前端与后端开发中的最佳实践，涵盖多语言方案选型、动态加载策略、语言包管理技巧及常见陷阱。从代码结构设计到用户体验优化，解析如何高效实现多语言支持，适用于Web开发工程师及全球化产品团队","frontmatter":{"title":"谈谈国际化的使用姿势(i18n)","description":"本文深入探讨i18n(国际化)在前端与后端开发中的最佳实践，涵盖多语言方案选型、动态加载策略、语言包管理技巧及常见陷阱。从代码结构设计到用户体验优化，解析如何高效实现多语言支持，适用于Web开发工程师及全球化产品团队","keywords":"i18n,vue-i18n,react-i18next,angular-localize,国际化自动化","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/icon-network.png"},"headers":[],"relativePath":"article/2023/i18n-tutorial.md","filePath":"article/2023/i18n-tutorial.md","lastUpdated":1776945570000}'),F={name:"article/2023/i18n-tutorial.md"};function D(b,s,u,d,m,h){const p=n("Obsolete"),e=n("Reward"),o=n("Gitalk");return r(),c("div",null,[s[0]||(s[0]=l("h1",{id:"谈谈国际化的使用姿势-i18n",tabindex:"-1"},[i("谈谈国际化的使用姿势(i18n) "),l("a",{class:"header-anchor",href:"#谈谈国际化的使用姿势-i18n","aria-label":'Permalink to "谈谈国际化的使用姿势(i18n)"'},"​")],-1)),a(p,{date:"2023-11-08"}),s[1]||(s[1]=y(`<p>国际化（Internationalization，简称 i18n）的核心目标是让产品能够适应不同语言、文化和地区的用户需求。其必要性体现在以下几个方面：</p><ul><li>用户覆盖广度：全球用户语言环境多样，支持多语言可提升用户体验，扩大市场范围</li><li>代码可维护性：通过统一管理多语言资源，避免硬编码文本分散在代码中，减少重复修改成本</li><li>动态适配能力：结合浏览器语言检测或用户手动切换，实现内容实时更新，无需重新部署代码</li></ul><p>通常一个中大型的项目都会实现国际化，开发人员只需要将对应语言的翻译根据映射到页面中就可以完成。在现代web框架以及国际化框架的加持下，整体功能的实现也越来越简单。如vue中通常使用 <a href="https://github.com/intlify/vue-i18n" target="_blank" rel="noreferrer">Vue-I18n</a>、React可以用 <a href="https://github.com/i18next/react-i18next" target="_blank" rel="noreferrer">React-I18next</a>、Angular提供了 <a href="https://github.com/angular/angular/tree/main/packages/localize" target="_blank" rel="noreferrer">localize</a>，这些都可以加速国际化开发</p><h2 id="开发流程" tabindex="-1">开发流程 <a class="header-anchor" href="#开发流程" aria-label="Permalink to &quot;开发流程&quot;">​</a></h2><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/translation-process.png" alt=""></p><p>在真实的项目开发中，常见的开发流程即：开发人员在编码的过程中，通常会将待翻译的文案提取到对应语言map中，最后通知翻译团队进行翻译，翻译完成后再更新到代码中，然后在测试过程中验证，有问题继续重复以上步骤</p><h2 id="i18n几种方案" tabindex="-1">i18n几种方案 <a class="header-anchor" href="#i18n几种方案" aria-label="Permalink to &quot;i18n几种方案&quot;">​</a></h2><p>i18n是现代国际化实现必不可缺的帮手，它提供了相对灵活的方案，开发者可以根据使用场景选择合适的方案快速实现国际化</p><p>下面就来看看项目中i18n的多种使用方式，本文按照由简到繁的顺序一一介绍，以vue-i18n为演示框架</p><div class="warning custom-block"><p class="custom-block-title">小贴士</p><p>本文只做国际化方案的演示介绍，不包括详细的配置步骤，读者可根据方案进行调整实现</p></div><h3 id="代码集成实现" tabindex="-1">代码集成实现 <a class="header-anchor" href="#代码集成实现" aria-label="Permalink to &quot;代码集成实现&quot;">​</a></h3><p>代码集成是i18n最常用的一种方案，它将所有需要翻译的文案统一到代码中，在编译时进行替换，从而实现国际化</p><p>首先创建i18n实例</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">// i18n实例</span></span>
<span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> i18n </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> createI18n</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  // 默认语音</span></span>
<span class="line"><span style="color:#F07178;">  locale</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">zh</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  // 备选语音(默认语音不存在时使用)</span></span>
<span class="line"><span style="color:#F07178;">  fallbackLocale</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">en</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  // 对应语言的翻译映射，以语言值为key，对应语言的翻译为value</span></span>
<span class="line"><span style="color:#F07178;">  messages</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">    en</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">      message</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">        hello</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">hello world</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#89DDFF;">      }</span></span>
<span class="line"><span style="color:#89DDFF;">    },</span></span>
<span class="line"><span style="color:#F07178;">    zh</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">      message</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">        hello</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">你好世界</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#89DDFF;">      }</span></span>
<span class="line"><span style="color:#89DDFF;">    }</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span><span style="color:#BABED8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p>在组件中使用</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">h1</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">{{ $t(&#39;message.hello&#39;) }}</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">h1</span><span style="color:#89DDFF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>当语言环境改变时，修改i18n的语言值就完成了翻译文案的切换</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#BABED8;">i18n</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">value </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">en</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>当翻译文件体量越来越大时，通常都会将翻译内容以语言划分文件夹，然后根据语义或者模块信息将内容分组后存储</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">i18n</span><span style="color:#BABED8;">  </span></span>
<span class="line"><span style="color:#FFCB6B;">└──</span><span style="color:#C3E88D;"> en        </span></span>
<span class="line"><span style="color:#FFCB6B;">    ├──</span><span style="color:#C3E88D;"> common.js  # 英文公共文件</span></span>
<span class="line"><span style="color:#FFCB6B;">    └──</span><span style="color:#C3E88D;"> login.js   # 登录页面英文翻译</span></span>
<span class="line"><span style="color:#FFCB6B;">└──</span><span style="color:#C3E88D;"> zh         </span></span>
<span class="line"><span style="color:#FFCB6B;">    ├──</span><span style="color:#C3E88D;"> common.js  # 中文公共文件</span></span>
<span class="line"><span style="color:#FFCB6B;">    └──</span><span style="color:#C3E88D;"> common.js  # 可能为重复或备用中文文件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>📌 <u>代码集成方式缺点：</u></p><ul><li>翻译同步维护难度大</li><li>翻译体积文件过大时，加载性能问题</li></ul><p>开发时通常都会用母语作为默认语言，然后其他的语言同步好对应的字段，交给翻译后进行翻译，当翻译内容好后再手动同步到对应的字段代码中，在后期多次需求开发时，如果翻译同步不及时会变得异常困难，而且手动同步也会变得很繁琐，成本太高开发体验很差</p><h3 id="基于json实现" tabindex="-1">基于JSON实现 <a class="header-anchor" href="#基于json实现" aria-label="Permalink to &quot;基于JSON实现&quot;">​</a></h3><p>基于JSON的方案顾名思义就是将翻译内容保存到JSON文件中，然后根据语言加载对应的JSON文件，完成国际化工作</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> i18n </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> createI18n</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">  locale</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">zh</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">  globalInjection</span><span style="color:#89DDFF;">:</span><span style="color:#FF9CAC;"> true</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">  missingWarn</span><span style="color:#89DDFF;">:</span><span style="color:#FF9CAC;"> false</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">  silentFallbackWarn</span><span style="color:#89DDFF;">:</span><span style="color:#FF9CAC;"> true</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">  silentTranslationWarn</span><span style="color:#89DDFF;">:</span><span style="color:#FF9CAC;"> true</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#89DDFF;">}</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">export</span><span style="color:#C792EA;"> async</span><span style="color:#C792EA;"> function</span><span style="color:#82AAFF;"> loadLangResource</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">i18n</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> locale</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#C792EA;">  const</span><span style="color:#BABED8;"> messages</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#82AAFF;"> import</span><span style="color:#F07178;">(</span><span style="color:#676E95;font-style:italic;">/* webpackChunkName: &quot;locale-[request]&quot; */</span><span style="color:#89DDFF;"> \`</span><span style="color:#C3E88D;">/static/</span><span style="color:#89DDFF;">\${</span><span style="color:#BABED8;">locale</span><span style="color:#89DDFF;">}</span><span style="color:#C3E88D;">.json</span><span style="color:#89DDFF;">\`</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  // 或者不参与打包</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">  // const messages = await fetch(\`/static/\${locale}.json?v=\${app.version}\`)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">  i18n</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">global</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">setLocaleMessage</span><span style="color:#F07178;">(</span><span style="color:#BABED8;">locale</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;"> messages</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">default</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>从上述代码中可以看到在对应的语言环境下，加载对应的JSON翻译文件，此种方式可以很好的将翻译与代码解耦，实现翻译共享与复用，并且翻译资源文件拆分异步加载可以提高加载性能</p><p>📌 <u>基于JSON方式缺点：</u></p><ul><li>翻译同步维护难度同样大</li><li>JSON中无法注释，需采用JSON5等方案</li></ul><p>JSON方式虽然与代码进行了解耦，但仍然存在翻译同步维护的困难，如JSON字段的维护怎么维护？没有注释就像天书。当然，这并不是JSON的最佳使用方案，这里也是简单介绍下此种方案，但简单的翻译工作也可以使用这种简单的JSON方案</p><p>头疼的是JSON怎么维护问题，接下来看看如何解决这个问题</p><h3 id="基于json与cms实现" tabindex="-1">基于JSON与CMS实现 <a class="header-anchor" href="#基于json与cms实现" aria-label="Permalink to &quot;基于JSON与CMS实现&quot;">​</a></h3><p>JSON方案虽然与代码解耦了，但开发者去修改JSON文件是万万不能接受的！！</p><p>如果可以将JSON字段用某个工具与翻译人员关联起来，那么就可以省不少事，并且翻译人员可以随时修改翻译内容，并通知更新。这里介绍2种方案：</p><ul><li>基于在线表格</li><li>基于数据库(CMS)</li></ul><p>来看看在线表格方案，什么意思呢：<u>开发人员将待翻译内容呈现在在线表格中，翻译人员直接在表格中同步翻译内容，最后通知开发者更新即可</u>。那么如何与JSON关联起来呢？要知道代码中i18n还是会以<code>key</code>为索引显示对应的翻译内容，所以表格中需要有对应的key字段，开发者需要创建key字段，最后将表格数据转换成json文件即可</p><p>这里关键的步骤在于如何将在线表格数据转换成JSON，其实很简单，市面上的文档如：Google、Tencent等等都支持API操作，读者可前往对应的开发者文档查看</p><p>本文用腾讯在线表格演示，如下图所示，在线表格中包含了：翻译表标题、表头、翻译内容，开发者提供对应的翻译字段key，翻译人员将翻译内容填入即可</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-04_09.18.07.png" alt=""></p><p>有了API数据后就可以转换成JSON了，可以用Node实现API请求然后生成对应的JSON文件</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;">// 伪代码</span></span>
<span class="line"><span style="color:#C792EA;">async</span><span style="color:#C792EA;"> function</span><span style="color:#82AAFF;"> getData</span><span style="color:#89DDFF;">()</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#C792EA;">  const</span><span style="color:#BABED8;"> data</span><span style="color:#89DDFF;"> =</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#82AAFF;"> fetch</span><span style="color:#F07178;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">https://domain.com/apii/sheet/uidlpsdfierersefadf</span><span style="color:#89DDFF;">&quot;</span><span style="color:#F07178;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">  data</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">json</span><span style="color:#F07178;">()</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">then</span><span style="color:#F07178;">(</span><span style="color:#BABED8;font-style:italic;">res</span><span style="color:#C792EA;"> =&gt;</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">    // 转换逻辑</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">    // 根据不同的语言生成对应的JSON文件</span></span>
<span class="line"><span style="color:#BABED8;">    fs</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">writeFileSync</span><span style="color:#F07178;">(</span><span style="color:#89DDFF;">\`\${</span><span style="color:#BABED8;">lang</span><span style="color:#89DDFF;">}</span><span style="color:#C3E88D;">.json</span><span style="color:#89DDFF;">\`</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;"> JSON</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">stringify</span><span style="color:#F07178;">(</span><span style="color:#BABED8;">res</span><span style="color:#F07178;">))</span><span style="color:#89DDFF;">\`</span><span style="color:#C3E88D;">.)</span></span>
<span class="line"><span style="color:#C3E88D;">  })</span></span>
<span class="line"><span style="color:#C3E88D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>将对应的i18n生成脚本写入到项目的package.json中</p><div class="language-json line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  &quot;</span><span style="color:#C792EA;">scripts</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#89DDFF;">    &quot;</span><span style="color:#FFCB6B;">i18n</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">node i18n.js</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这样每次在翻译表格更新后，直接走脚本就行了，开发者无需去关心JSON文件长啥样了。同样的再走完上文中JSON中i18n的json加载逻辑，即可完成多语言的切换</p><p>接着看看CMS(Content Management System)与JSON的结合使用，其实在线表格的方式已经减少了很大一部分工作，但对于企业来说维护自己的翻译系统还是必要的</p><p>设计这一套系统也非常简单，服务端只需要使用以下条件可快速实现：</p><ul><li>数据库：使用mongodb非关系型数据库无需关注字段的数量，可以满足多语言的多样性数据</li><li>数据表：项目语言表、具体语言表</li></ul><p>总体来说使用mongodb创建一个不同项目的语言表和具体语言表就基本满足了项目使用了</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-04_09.56.51.png" alt=""></p><p>CMS当然还需要实现在线表格的功能，或者说客户端页面使用功能，基本要满足：语言表创建、修改、查询等等，市面上有很多方式可以帮助到，这里就不细讲了</p><p>来看这是CMS中AI Chat项目的语言表</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-04_09.26.45.png" alt=""></p><p>开发团队可以定制具体的规则来标准化开发流程，如：不同的颜色代表不同的含义</p><p>除此之外，可以根据RBAC权限来控制语言表的访问</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2025-05-04_09.28.04.png" alt=""></p><p>那么在项目中如何拉取语言表呢？通常在项目中新增env配置：</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#BABED8;">I18N_TABLE_KEY</span><span style="color:#89DDFF;">=</span><span style="color:#C3E88D;">xxxx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>根据项目语言表的key就可以拉取数据了，同样的重复上文中的脚本操作完成json文件的生成</p><p>你是否在想如果有了CMS是不是可以直接跳过JSON文件载体，直接走API？其实也不是不可以，只不过JSON方式更稳妥，至于为什么读者可以多考虑考虑</p><p>📌 <u>基于CMS与JSON方式缺点：</u></p><ul><li>架构复杂</li></ul><h3 id="基于插件自动化实现" tabindex="-1">基于插件自动化实现 <a class="header-anchor" href="#基于插件自动化实现" aria-label="Permalink to &quot;基于插件自动化实现&quot;">​</a></h3><p>话说回来国际化的实现过程确实很痛苦，要维护密密麻麻的翻译，何尝不相信自动化翻译呢？</p><p>我们可以借助翻译服务商提供翻译接口自动将文案翻译成目标语言，然后通过自动化插件将翻译后的文案自动填充到项目文件中，从而实现国际化</p><p>这种方式的维护成本很低，开发者根本不需要管翻译内容，一般实现步骤如下：</p><ol><li>项目中直接用默认语言写入文案，然后标记当前位置需要翻译</li></ol><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">h1</span><span style="color:#C792EA;"> m-translate</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">你好</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">h1</span><span style="color:#89DDFF;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="2"><li>编写翻译转换脚本，可以使用Babel自定义插件编译AST，找到标记的待翻译节点，然后为当前文案生成唯一的key，将文案替换为key后，再将文案翻译成多种目标语言</li></ol><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> translateAPI </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> require</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">google-translate-api</span><span style="color:#89DDFF;">&quot;</span><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">export</span><span style="color:#C792EA;"> const</span><span style="color:#BABED8;"> AutoTranslatePlugin </span><span style="color:#89DDFF;">=</span><span style="color:#82AAFF;"> declare</span><span style="color:#BABED8;">(</span></span>
<span class="line"><span style="color:#89DDFF;">  ({</span><span style="color:#BABED8;font-style:italic;"> assertVersion</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> types</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> template</span><span style="color:#89DDFF;"> })</span><span style="color:#C792EA;"> =&gt;</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#82AAFF;">    assertVersion</span><span style="color:#F07178;">(</span><span style="color:#F78C6C;">7</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">    return</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">      name</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &quot;</span><span style="color:#C3E88D;">AutoTranslatePlugin</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#F07178;">      visitor</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#F07178;">        Expression</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">path</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">          // 走服务商翻译 translateAPI</span></span>
<span class="line"><span style="color:#89DDFF;">        },</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">        // 补充...</span></span>
<span class="line"><span style="color:#89DDFF;">      },</span></span>
<span class="line"><span style="color:#89DDFF;">    };</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#BABED8;">)</span><span style="color:#89DDFF;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><ol start="3"><li>生成对应的最终的翻译JSON文件 在插件遍历AST以及翻译过程中将生成的文案key整理后生成到对应的JSON文件中，这样就实现了文案自动化处理</li></ol><p>📌 <u>基于插件自动化方式缺点：</u></p><ul><li>翻译质量不可控</li></ul><h2 id="方案对比" tabindex="-1">方案对比 <a class="header-anchor" href="#方案对比" aria-label="Permalink to &quot;方案对比&quot;">​</a></h2><table><thead><tr><th style="text-align:left;">方案</th><th style="text-align:left;">适用场景</th><th style="text-align:left;">核心优势</th><th style="text-align:left;">主要缺点</th></tr></thead><tbody><tr><td style="text-align:left;">代码集成</td><td style="text-align:left;">中小型项目</td><td style="text-align:left;">实现简单，社区支持完善</td><td style="text-align:left;">维护成本高，翻译同步困难</td></tr><tr><td style="text-align:left;">CMS 动态管理</td><td style="text-align:left;">非技术团队协作</td><td style="text-align:left;">内容可实时更新，灵活性高</td><td style="text-align:left;">强依赖网络，架构复杂</td></tr><tr><td style="text-align:left;">自动化工具</td><td style="text-align:left;">多语言快速迭代</td><td style="text-align:left;">减少人工干预，提升效率</td><td style="text-align:left;">翻译质量依赖 API，成本不可控</td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本文通过不同角度介绍了国际化的实现方案，以及它们各自的优缺点，读者可根据项目要求或开发标准选择适合的方案。透露下本人工作中常使用<code>CMS+JSON</code>方式，如果你还有更好的方案，可留言分享</p>`,76)),a(e),a(o)])}const B=t(F,[["render",D]]);export{A as __pageData,B as default};
